pub(super) fn exact_file_path(path: &Path, label: &str) -> Result<PathBuf> {
    let path = fs::canonicalize(path)
        .with_context(|| format!("foreign-process {label} path is unavailable"))?;
    if !path.is_absolute() {
        bail!("foreign-process {label} path must resolve absolutely");
